        if (t) {
            setThings('done');
        }
    }

    function fetchMoreThings() {
        return fetchThings();
    }

    const mapping = {
        something: things
    };

    useEffect(() => {
        fetchThings();
        const fetchData = async () => {
            await fetchMoreThings();
